#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_camera_projection_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=2)throw std::runtime_error("session required");auto g=loadGraph(argv[1]);uint32_t first=UINT32_MAX;size_t count=0,ortho=0;for(uint32_t n=0;n<g.elements.size();++n)if(g.strings.at(g.elements[n].type)=="DmeCamera"){auto c=readSessionCameraSettingsCandidate(g,n);auto projection=sessionCameraProjectionCandidate(g,n,1920,1080,true);if(projection.rows[0]<=0||projection.rows[5]>=0)throw std::runtime_error("session perspective projection");if(first==UINT32_MAX)first=n;++count;ortho+=c.orthographic;std::cout<<"camera="<<n<<" transform="<<c.transform<<" fov="<<c.fieldOfView<<" near="<<c.nearPlane<<" far="<<c.farPlane<<" ortho="<<c.orthographic<<'\n';}if(first==UINT32_MAX)throw std::runtime_error("no cameras");auto&camera=g.elements[first];auto mutate=[&](const char*name,auto edit){for(auto&a:camera.attributes)if(g.strings.at(a.name)==name){auto saved=a;edit(a);bool rejected=false;try{readSessionCameraSettingsCandidate(g,first);}catch(const std::runtime_error&){rejected=true;}a=std::move(saved);if(!rejected)throw std::runtime_error("camera mutation accepted");return;}throw std::runtime_error("missing fixture field");};mutate("fieldOfView",[](Attribute&a){setFloat(a,0,0);});mutate("znear",[](Attribute&a){setFloat(a,0,-1);});mutate("zfar",[](Attribute&a){setFloat(a,0,1);});mutate("transform",[](Attribute&a){a.values[0].reference=UINT32_MAX;});mutate("ortho",[](Attribute&a){a.values[0].wire[0]=2;});mutate("fieldOfView",[](Attribute&a){a.type=2;});std::cout<<"x64 session camera settings passed cameras="<<count<<" orthographic="<<ortho<<" rejected=6 graph_modified=no\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}

